-- Transitioning from unnormalized to 3NF/BCNF Schema

-- Unnormalized Table (Violates 1NF, 2NF, 3NF)
CREATE TABLE employee_project_unnormalized (
    emp_id INT,
    emp_name VARCHAR(100),
    dept_id INT,
    dept_name VARCHAR(100), -- Transitive: dept_id -> dept_name
    project_code VARCHAR(50), 
    project_cost DECIMAL(10,2) -- Partial: depends only on project_code
);

-- Normalized Schema (3NF / BCNF Compliant)
CREATE TABLE department (
    dept_id INT PRIMARY KEY,
    dept_name VARCHAR(100) NOT NULL
);

CREATE TABLE employee (
    emp_id INT PRIMARY KEY,
    emp_name VARCHAR(100) NOT NULL,
    dept_id INT NOT NULL,
    CONSTRAINT fk_dept FOREIGN KEY (dept_id) REFERENCES department(dept_id)
);

CREATE TABLE project (
    project_code VARCHAR(50) PRIMARY KEY,
    project_cost DECIMAL(10,2) NOT NULL
);

CREATE TABLE employee_project_assignment (
    emp_id INT,
    project_code VARCHAR(50),
    PRIMARY KEY (emp_id, project_code),
    CONSTRAINT fk_emp FOREIGN KEY (emp_id) REFERENCES employee(emp_id),
    CONSTRAINT fk_proj FOREIGN KEY (project_code) REFERENCES project(project_code)
);
